const ExcelJS = require('exceljs');
const wb = new ExcelJS.Workbook();

const HEADERS = [
  'Test Case ID', 'Module/Section', 'Test Scenario', 'Priority',
  'Test Steps', 'Test Data', 'Expected Result',
  'Actual Result', 'Pass/Fail', 'Comments/Issues', 'Tester Name', 'Test Date', 'How to Test'
];
const HEADER_FILL = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F4E79' } };
const HEADER_FONT = { bold: true, color: { argb: 'FFFFFFFF' }, size: 11, name: 'Arial' };
const ALT_FILL = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F7FB' } };
const BORDER = { top: { style: 'thin' }, bottom: { style: 'thin' }, left: { style: 'thin' }, right: { style: 'thin' } };

function addSheet(name, cases) {
  const ws = wb.addWorksheet(name);
  const hr = ws.addRow(HEADERS);
  hr.eachCell(cell => { cell.fill = HEADER_FILL; cell.font = HEADER_FONT; cell.border = BORDER; cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true }; });
  ws.getColumn(1).width = 15; ws.getColumn(2).width = 20; ws.getColumn(3).width = 35; ws.getColumn(4).width = 10;
  ws.getColumn(5).width = 50; ws.getColumn(6).width = 30; ws.getColumn(7).width = 40;
  ws.getColumn(8).width = 40; ws.getColumn(9).width = 10; ws.getColumn(10).width = 30; ws.getColumn(11).width = 15; ws.getColumn(12).width = 12; ws.getColumn(13).width = 80;
  cases.forEach((c, i) => {
    const row = ws.addRow([c.id, c.section, c.scenario, c.priority, c.steps, c.testData, c.expected, '', '', '', '', '', c.howToTest || '']);
    row.eachCell(cell => { cell.border = BORDER; cell.alignment = { vertical: 'top', wrapText: true }; });
    if (i % 2 === 1) row.eachCell(cell => { cell.fill = ALT_FILL; });
  });
  ws.autoFilter = { from: 'A1', to: 'M1' };
  ws.views = [{ state: 'frozen', ySplit: 1 }];
  return ws;
}

