// ========== SPARES ADDITIONAL (25 cases) ==========
const sparesCases = [
  { id: 'SP-041', section: 'By Location Tab', scenario: 'View spares grouped by storage location', priority: 'Medium', steps: '1. Navigate to Spares\n2. Click "By Location" tab\n3. Verify grouping', testData: 'N/A', expected: 'Spares displayed grouped by physical storage location (Engine Room, Deck Store, etc.)', howToTest: 'HOW TO TEST:\n1. Navigate to PMS > Spares and select a vessel.\n2. Click the "By Location" tab.\n3. VERIFY: Spares are grouped by their physical storage location.\n4. VERIFY: Each location group shows the location name and the spares stored there.\n5. VERIFY: Quantities are shown per spare within each location.' },
  { id: 'SP-042', section: 'By Location Tab', scenario: 'Location A and B quantities displayed', priority: 'Medium', steps: '1. View By Location tab\n2. Check spare with dual locations\n3. Verify qty shown per location', testData: 'Spare with stock in both locations', expected: 'Shows Location A qty and Location B qty separately. Total ROB = sum.', howToTest: 'HOW TO TEST:\n1. In the By Location tab, find a spare with stock in both Location A and Location B.\n2. VERIFY: Location A quantity is shown separately.\n3. VERIFY: Location B quantity is shown separately.\n4. VERIFY: Total ROB = Location A qty + Location B qty.\n5. VERIFY: Both location values match what is shown in the main Spares list.' },
  { id: 'SP-043', section: 'History Tab', scenario: 'View spare transaction ledger', priority: 'High', steps: '1. Navigate to Spares > History tab\n2. Select a spare\n3. Verify ledger entries', testData: 'N/A', expected: 'Ledger shows all transactions: Date, Type (Consume/Receive/Transfer/Adjust), Qty, Running Balance', howToTest: 'HOW TO TEST:\n1. Navigate to PMS > Spares and click the "History" tab.\n2. Search for and select a spare part.\n3. VERIFY: A ledger/transaction history is displayed.\n4. VERIFY: Each entry shows: Date, Transaction Type, Quantity, Running Balance.\n5. VERIFY: Transaction types include Consume, Receive, Transfer, and Adjust.\n6. VERIFY: The running balance is mathematically correct for each entry.' },
  { id: 'SP-044', section: 'History Tab', scenario: 'Filter history by event type', priority: 'Medium', steps: '1. View spare history\n2. Filter by event type (Consume only)\n3. Verify filtered results', testData: 'Filter: Consume', expected: 'Only consume transactions displayed', howToTest: 'HOW TO TEST:\n1. In Spares History, select a spare with multiple transaction types.\n2. Apply the event type filter and select "Consume" only.\n3. VERIFY: Only consume transactions are displayed.\n4. VERIFY: Receive, Transfer, and Adjust entries are hidden.\n5. Change filter to "Receive" and VERIFY only receive entries show.' },
  { id: 'SP-045', section: 'History Tab', scenario: 'Filter history by date range', priority: 'Medium', steps: '1. View spare history\n2. Set Date From and Date To\n3. Verify filtered results', testData: 'From: 01-Jan, To: 31-Mar', expected: 'Only transactions within date range displayed', howToTest: 'HOW TO TEST:\n1. In Spares History, select a spare.\n2. Set Date From: 01-Jan-2026, Date To: 31-Mar-2026.\n3. VERIFY: Only transactions within Jan-Mar 2026 are shown.\n4. VERIFY: Transactions outside this range are hidden.' },
  { id: 'SP-046', section: 'Add Spare', scenario: 'Add spare with Maker List integration', priority: 'Medium', steps: '1. Click Add Spare\n2. In Maker field, search from Maker List\n3. Select maker\n4. Save', testData: 'Maker: From fleet maker database', expected: 'Maker validated against central fleet maker database. Spare saved with linked maker.', howToTest: 'HOW TO TEST:\n1. Navigate to Spares and click "Add Spare".\n2. In the Maker field, start typing a maker name.\n3. VERIFY: A dropdown or search suggests makers from the fleet-wide maker database.\n4. Select a maker from the suggestions.\n5. Complete other required fields and save.\n6. VERIFY: The spare is saved with the selected maker linked.' },
  { id: 'SP-047', section: 'Add Spare', scenario: 'Add spare with IHM status', priority: 'Medium', steps: '1. Click Add Spare\n2. Toggle IHM status on\n3. Set hazard category\n4. Save', testData: 'IHM: Yes, Category: Table A', expected: 'Spare created with IHM flag. Visible in IHM module.', howToTest: 'HOW TO TEST:\n1. Click "Add Spare" in the Spares module.\n2. Toggle the IHM (Inventory of Hazardous Materials) status to "Yes".\n3. VERIFY: Additional fields appear (Hazard Category, etc.).\n4. Select "Table A" as the hazard category.\n5. Fill in other fields and save.\n6. VERIFY: The spare shows an IHM indicator in the spares list.\n7. Navigate to the IHM module and VERIFY the spare appears there.' },
  { id: 'SP-048', section: 'Transaction', scenario: 'Consume/Receive selection step', priority: 'High', steps: '1. Click transaction button on spare\n2. Verify selection dialog (Consume or Receive)\n3. Select one', testData: 'N/A', expected: 'Selection step shows Consume vs Receive options. Correct form opens after selection.', howToTest: 'HOW TO TEST:\n1. Navigate to Spares and find a spare with stock.\n2. Click the transaction button (e.g., +/- icon or "Transaction" button).\n3. VERIFY: A selection dialog appears with options: "Consume" and "Receive".\n4. Select "Consume" and VERIFY the consume form opens.\n5. Cancel, click transaction again, select "Receive" and VERIFY the receive form opens.' },
  { id: 'SP-049', section: 'Transaction', scenario: 'Consume spare from specific location', priority: 'High', steps: '1. Select Consume\n2. Choose Location A or B\n3. Enter quantity\n4. Save', testData: 'Location: A, Qty: 3', expected: 'Stock decremented from selected location only. Other location unchanged.', howToTest: 'HOW TO TEST:\n1. Note the current stock at Location A and Location B for a spare.\n2. Initiate a Consume transaction.\n3. Select "Location A" as the source.\n4. Enter quantity: 3.\n5. Save.\n6. VERIFY: Location A stock decreased by 3.\n7. VERIFY: Location B stock is unchanged.\n8. VERIFY: Total ROB decreased by 3.' },
  { id: 'SP-050', section: 'Transaction', scenario: 'Receive spare to specific location', priority: 'High', steps: '1. Select Receive\n2. Choose Location\n3. Enter qty, date, optional WO/Supplier/Remarks\n4. Save', testData: 'Location: B, Qty: 10, Supplier: "Marine Parts"', expected: 'Stock incremented at selected location. Transaction logged with receipt details.', howToTest: 'HOW TO TEST:\n1. Initiate a Receive transaction for a spare.\n2. Select "Location B".\n3. Enter qty: 10, date: today, supplier: "Marine Parts".\n4. Save.\n5. VERIFY: Location B stock increased by 10.\n6. VERIFY: Transaction logged with supplier name and receipt date.\n7. Check History tab to VERIFY the receive entry is recorded.' },
  { id: 'SP-051', section: 'Transaction', scenario: 'Adjust stock quantity', priority: 'Medium', steps: '1. Open Adjust modal\n2. Set new quantity for location\n3. Enter reason\n4. Save', testData: 'Adjust: 10 → 8, Reason: "Physical count"', expected: 'Stock adjusted. Transaction logged as "Adjust" with reason.', howToTest: 'HOW TO TEST:\n1. Open the stock adjustment option for a spare.\n2. Change the quantity from 10 to 8.\n3. Enter reason: "Physical count".\n4. Save.\n5. VERIFY: Stock is now 8.\n6. Check History and VERIFY an "Adjust" transaction is logged with the reason.' },
  { id: 'SP-052', section: 'Location Management', scenario: 'Rename Location A/B for a spare', priority: 'Low', steps: '1. Open spare details\n2. Click location settings\n3. Rename "Location A" to "Engine Room Store"\n4. Save', testData: 'New name: "Engine Room Store"', expected: 'Location label renamed. Displayed with custom name across spare views.', howToTest: 'HOW TO TEST:\n1. Open a spare\'s details.\n2. Find the location settings or edit option.\n3. Rename "Location A" to "Engine Room Store".\n4. Save.\n5. VERIFY: The custom name appears everywhere the location is referenced.\n6. VERIFY: Transactions now show "Engine Room Store" instead of "Location A".' },
  { id: 'SP-053', section: 'Location Management', scenario: 'Move stock between locations', priority: 'Medium', steps: '1. Open spare\n2. Click Transfer\n3. From Location A to B, qty 5\n4. Save', testData: 'Transfer: A→B, Qty: 5', expected: 'Location A decremented by 5, Location B incremented by 5. Transfer logged.', howToTest: 'HOW TO TEST:\n1. Note current stock at Location A (e.g., 10) and Location B (e.g., 5).\n2. Initiate a Transfer transaction.\n3. Set From: Location A, To: Location B, Qty: 5.\n4. Save.\n5. VERIFY: Location A = 5, Location B = 10.\n6. VERIFY: Total ROB unchanged (still 15).\n7. Check History for a "Transfer" entry.' },
  { id: 'SP-054', section: 'Bulk Operations', scenario: 'Bulk deactivate multiple spares', priority: 'Medium', steps: '1. Select multiple spares via checkboxes\n2. Click "Bulk Deactivate"\n3. Confirm', testData: '5 spares selected', expected: 'All 5 spares deactivated. Removed from active inventory. Can be restored.', howToTest: 'HOW TO TEST:\n1. In the Spares list, check the checkboxes for 5 spares.\n2. Click "Bulk Deactivate".\n3. VERIFY: A confirmation dialog appears listing the 5 spares.\n4. Confirm.\n5. VERIFY: All 5 spares are removed from the active list.\n6. If available, check an "Inactive" filter and VERIFY they appear there.' },
  { id: 'SP-055', section: 'Modify Mode', scenario: 'Edit spare in Modify mode creates CR', priority: 'High', steps: '1. Enter Modify mode\n2. Edit spare description or min stock\n3. Click Propose Changes', testData: 'Change: Min stock 5 → 10', expected: 'Change Request created for spare modification. Red border on changed field.', howToTest: 'HOW TO TEST:\n1. Enter Modify Mode (PMS > Modify PMS).\n2. Navigate to Spares.\n3. Select a spare and edit the Min Stock from 5 to 10.\n4. VERIFY: The changed field shows a red border indicator.\n5. Click "Propose Changes" or "Review & Submit".\n6. VERIFY: A Change Request is created for the spare modification.\n7. Check the CR list and VERIFY it appears there.' },
  { id: 'SP-056', section: 'Stock Status Filter', scenario: 'Filter by Out of Stock', priority: 'Medium', steps: '1. Navigate to Spares\n2. Set Stock Status filter to "Out of Stock"\n3. Verify results', testData: 'Filter: Out of Stock', expected: 'Only spares with ROB = 0 displayed', howToTest: 'HOW TO TEST:\n1. Navigate to PMS > Spares and select a vessel.\n2. Find the Stock Status filter dropdown.\n3. Select "Out of Stock".\n4. VERIFY: Only spares with ROB = 0 are displayed.\n5. VERIFY: All visible spares show zero quantity.' },
  { id: 'SP-057', section: 'Stock Status Filter', scenario: 'Filter by Below Minimum', priority: 'Medium', steps: '1. Set Stock Status to "Below Min"\n2. Verify results', testData: 'Filter: Below Min', expected: 'Only spares with ROB < minimum stock level displayed', howToTest: 'HOW TO TEST:\n1. Set the Stock Status filter to "Below Min".\n2. VERIFY: Only spares where ROB < Min Stock are displayed.\n3. VERIFY: Each visible spare shows ROB less than its configured minimum.\n4. VERIFY: Spares with no minimum set are excluded from this filter.' },
  { id: 'SP-058', section: 'Stock Status Filter', scenario: 'Filter by Well Stocked', priority: 'Low', steps: '1. Set Stock Status to "Well Stocked"\n2. Verify results', testData: 'Filter: Well Stocked', expected: 'Only spares with ROB >= minimum stock level displayed', howToTest: 'HOW TO TEST:\n1. Set the Stock Status filter to "Well Stocked".\n2. VERIFY: Only spares where ROB >= Min Stock are shown.\n3. VERIFY: No low-stock or out-of-stock spares appear in the filtered list.' },
  { id: 'SP-059', section: 'Add Spare', scenario: 'Add spare with Drawing and Position numbers', priority: 'Low', steps: '1. Click Add Spare\n2. Enter Drawing No and Position No\n3. Save', testData: 'Drawing: DRW-001, Position: P-05', expected: 'Spare saved with drawing and position reference data.', howToTest: 'HOW TO TEST:\n1. Click "Add Spare".\n2. Fill required fields.\n3. Enter Drawing No: DRW-001 and Position No: P-05.\n4. Save.\n5. VERIFY: The spare is saved with drawing and position data.\n6. Open the spare details and VERIFY DRW-001 and P-05 are displayed.' },
  { id: 'SP-060', section: 'Component Link', scenario: 'View components linked to spare', priority: 'Medium', steps: '1. Open spare details\n2. Check component link section\n3. Verify linked component', testData: 'N/A', expected: 'Shows component code, name, and SFI path that this spare belongs to.', howToTest: 'HOW TO TEST:\n1. Open a spare\'s detail view.\n2. Look for a "Linked Component" or "Component" section.\n3. VERIFY: The linked component code, name, and SFI path are displayed.\n4. VERIFY: Clicking the component link navigates to the Components module showing that component.' },
  { id: 'SP-061', section: 'Edge Cases', scenario: 'Negative stock prevention', priority: 'High', steps: '1. Try consuming more than available stock\n2. Verify prevention', testData: 'Available: 3, Consume: 5', expected: 'Error: "Insufficient stock. Available: 3." Transaction blocked.', howToTest: 'HOW TO TEST:\n1. Find a spare with ROB = 3.\n2. Initiate a Consume transaction.\n3. Enter quantity: 5.\n4. Try to save.\n5. VERIFY: An error message appears: "Insufficient stock" or similar.\n6. VERIFY: The transaction is blocked and stock remains at 3.' },
  { id: 'SP-062', section: 'Edge Cases', scenario: 'Spare with zero minimum stock not in alerts', priority: 'Low', steps: '1. Create spare with min stock = 0\n2. Set ROB = 0\n3. Verify not in low stock alerts', testData: 'Min Stock: 0, ROB: 0', expected: 'Spare not flagged as low stock (min stock is 0, so no alert threshold).', howToTest: 'HOW TO TEST:\n1. Create or edit a spare with Min Stock = 0 and ROB = 0.\n2. Navigate to any low stock alert or report.\n3. VERIFY: This spare does NOT appear in the low stock list.\n4. VERIFY: Only spares with Min Stock > 0 and ROB < Min Stock are flagged.' },
  { id: 'SP-063', section: 'Criticality Filter', scenario: 'Filter spares by Critical status', priority: 'Medium', steps: '1. Navigate to Spares\n2. Enable Criticality filter\n3. Verify filtered results', testData: 'Filter: Critical', expected: 'Only spares marked as "Critical" displayed', howToTest: 'HOW TO TEST:\n1. Navigate to PMS > Spares.\n2. Find the Criticality filter and select "Critical".\n3. VERIFY: Only spares marked as critical are displayed.\n4. VERIFY: Non-critical spares are hidden from the list.' },
  { id: 'SP-064', section: 'Export', scenario: 'Export spares inventory to CSV', priority: 'Medium', steps: '1. Navigate to Spares\n2. Apply filters\n3. Click Export\n4. Download', testData: 'N/A', expected: 'CSV file with all visible spares data including ROB, locations, and status', howToTest: 'HOW TO TEST:\n1. Navigate to Spares and apply any desired filters.\n2. Click the "Export" button.\n3. VERIFY: A CSV file downloads.\n4. Open it and VERIFY columns include: Code, Name, ROB, Min Stock, Location A, Location B, Status.\n5. VERIFY: Only filtered (visible) spares are included.' },
  { id: 'SP-065', section: 'Edit Spare', scenario: 'Edit spare technical details', priority: 'Medium', steps: '1. Open spare\n2. Click Edit\n3. Modify technical details (Manual Reference)\n4. Save', testData: 'Manual: "Service Manual Rev 3"', expected: 'Technical details updated and saved.', howToTest: 'HOW TO TEST:\n1. Open a spare\'s details.\n2. Click "Edit".\n3. Modify the Manual Reference field to "Service Manual Rev 3".\n4. Save.\n5. VERIFY: The updated manual reference is displayed in the spare details.\n6. VERIFY: The change is persisted after page refresh.' },
];

// ========== STORES ADDITIONAL (25 cases) ==========
const storesCases = [
  { id: 'ST-026', section: 'Category Tabs', scenario: 'Navigate between Stores/Lubes/Chemicals/Others tabs', priority: 'High', steps: '1. Navigate to Stores\n2. Click each category tab\n3. Verify data changes per tab', testData: 'All 4 tabs', expected: 'Each tab shows items specific to that category. Counts update per tab.', howToTest: 'HOW TO TEST:\n1. Navigate to PMS > Stores and select a vessel.\n2. Click the "Stores" tab. VERIFY items specific to general stores are shown.\n3. Click "Lubes" tab. VERIFY only lubricants/oils are displayed.\n4. Click "Chemicals" tab. VERIFY only chemicals are shown (with safety fields).\n5. Click "Others" tab. VERIFY miscellaneous items are displayed.\n6. VERIFY: Item counts update correctly for each tab.' },
  { id: 'ST-027', section: 'View Modes', scenario: 'Switch between Inventory/Location/History sub-views', priority: 'Medium', steps: '1. Select a category tab\n2. Switch between Inventory, Location, and History sub-views\n3. Verify each view', testData: 'N/A', expected: 'Inventory: list view. Location: grouped by storage. History: transaction ledger.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores and select any category tab.\n2. Click "Inventory" sub-view. VERIFY: List of items with quantities.\n3. Click "Location" sub-view. VERIFY: Items grouped by storage location.\n4. Click "History" sub-view. VERIFY: Transaction ledger with dates and types.\n5. VERIFY: Each sub-view loads correctly without errors.' },
  { id: 'ST-028', section: 'Chemicals', scenario: 'Add chemical item with safety fields', priority: 'High', steps: '1. Click Chemicals tab\n2. Add new item\n3. Fill: UN Number, Flash Point, Storage Temp, PPE, Disposal\n4. Save', testData: 'UN: 1203\nFlash Point: 23°C\nPPE: Gloves, Goggles', expected: 'Chemical item created with all safety fields. SDS reference linkable.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Chemicals tab.\n2. Click "Add Item".\n3. Fill in the item name.\n4. Enter UN Number: 1203, Flash Point: 23°C.\n5. Set Storage Temperature range.\n6. Select PPE: Gloves, Goggles.\n7. Enter Disposal Instructions.\n8. Save.\n9. VERIFY: Chemical item is created with all safety data visible.\n10. VERIFY: SDS (Safety Data Sheet) reference field is available.' },
  { id: 'ST-029', section: 'Chemicals', scenario: 'Chemical expiry date tracking', priority: 'High', steps: '1. Navigate to Chemicals\n2. Check items with expiry dates\n3. Verify visual indicators', testData: 'Item with expired date', expected: 'Expired items show red indicator. Near-expiry (30 days) show amber warning.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Chemicals.\n2. Find an item with an expiry date in the past.\n3. VERIFY: A red indicator or badge shows "Expired".\n4. Find an item expiring within 30 days.\n5. VERIFY: An amber/yellow warning indicator is shown.\n6. VERIFY: Items with future expiry dates show no warning.' },
  { id: 'ST-030', section: 'Chemicals', scenario: 'SDS (Safety Data Sheet) reference', priority: 'Medium', steps: '1. Open chemical item\n2. Check SDS field\n3. Verify link/download if present', testData: 'N/A', expected: 'SDS reference field available. Can link to or upload safety data sheet.', howToTest: 'HOW TO TEST:\n1. Open a chemical item\'s details.\n2. Locate the SDS (Safety Data Sheet) field.\n3. VERIFY: The field exists and can hold a reference or file.\n4. If an SDS is uploaded, VERIFY it can be downloaded or viewed.\n5. If no SDS, VERIFY the field can accept an upload.' },
  { id: 'ST-031', section: 'Chemicals', scenario: 'Storage temperature min/max', priority: 'Medium', steps: '1. Add/Edit chemical\n2. Set Storage Temp Min and Max\n3. Save', testData: 'Min: 5°C, Max: 25°C', expected: 'Storage temperature range saved and displayed on chemical details.', howToTest: 'HOW TO TEST:\n1. Edit a chemical item.\n2. Set Storage Temp Min: 5°C, Max: 25°C.\n3. Save.\n4. VERIFY: The temperature range is saved and visible in the item details.\n5. VERIFY: The values persist after page refresh.' },
  { id: 'ST-032', section: 'Chemicals', scenario: 'Disposal instructions field', priority: 'Low', steps: '1. Add/Edit chemical\n2. Enter disposal instructions\n3. Save', testData: 'Disposal: "Return to shore facility"', expected: 'Disposal instructions saved and visible on item details.', howToTest: 'HOW TO TEST:\n1. Edit a chemical item.\n2. Enter disposal instructions: "Return to shore facility".\n3. Save.\n4. VERIFY: Disposal instructions are displayed in the item details.\n5. VERIFY: The text is complete and untruncated.' },
  { id: 'ST-033', section: 'Lubes', scenario: 'View Lubes tab with oil tracking', priority: 'Medium', steps: '1. Click Lubes tab\n2. Verify lube-specific fields displayed\n3. Check stock levels', testData: 'N/A', expected: 'Lubes tab shows oil types, grades, consumption rates, and quality tracking.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Lubes tab.\n2. VERIFY: Lube oil items are listed with relevant fields.\n3. VERIFY: Fields may include oil type, grade, viscosity, consumption rate.\n4. VERIFY: Stock levels (ROB) are displayed for each lube item.' },
  { id: 'ST-034', section: 'IHM Management', scenario: 'Set IHM Presence on store item', priority: 'Medium', steps: '1. Edit store item\n2. Toggle IHM Presence on\n3. Select Evidence Type\n4. Save', testData: 'IHM: Present\nEvidence: SDoC', expected: 'IHM data saved. Presence marked. Evidence type set (MD/SDoC/Test).', howToTest: 'HOW TO TEST:\n1. Edit a store item.\n2. Toggle "IHM Presence" to on/yes.\n3. VERIFY: Evidence Type field appears.\n4. Select "SDoC" (Supplier Declaration of Conformity).\n5. Save.\n6. VERIFY: IHM Presence is marked on the item.\n7. VERIFY: The item appears in IHM-related reports.' },
  { id: 'ST-035', section: 'IMPA Code', scenario: 'Enter IMPA code for store item', priority: 'Low', steps: '1. Add/Edit store item\n2. Enter IMPA code\n3. Save', testData: 'IMPA: 370101', expected: 'IMPA code saved. Searchable by IMPA code in search bar.', howToTest: 'HOW TO TEST:\n1. Edit a store item.\n2. Enter IMPA code: 370101.\n3. Save.\n4. VERIFY: The IMPA code is saved and visible in item details.\n5. Search for "370101" in the stores search bar.\n6. VERIFY: The item appears in search results when searching by IMPA code.' },
  { id: 'ST-036', section: 'History View', scenario: 'Filter history by event type', priority: 'Medium', steps: '1. Navigate to History sub-view\n2. Filter by Event Type (Receive/Consume/Edit/Transfer)\n3. Verify filtered', testData: 'Filter: Receive', expected: 'Only Receive events shown in history', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > History sub-view.\n2. Select an item and apply Event Type filter: "Receive".\n3. VERIFY: Only Receive transactions are shown.\n4. Switch to "Consume" and VERIFY only consume entries appear.' },
  { id: 'ST-037', section: 'History View', scenario: 'Filter history by date range', priority: 'Medium', steps: '1. Navigate to History\n2. Set date range\n3. Verify filtered results', testData: 'From: 01-Jan, To: 28-Feb', expected: 'Only transactions within date range displayed', howToTest: 'HOW TO TEST:\n1. In Stores History, set Date From: 01-Jan-2026, Date To: 28-Feb-2026.\n2. VERIFY: Only transactions within Jan-Feb 2026 are displayed.\n3. VERIFY: Entries outside this range are hidden.' },
  { id: 'ST-038', section: 'Batch Operations', scenario: 'Batch Receive with Location A/B', priority: 'High', steps: '1. Select batch operation\n2. Choose Receive\n3. Enter qty for Location A and/or B\n4. Save', testData: 'Location A: 10, Location B: 5', expected: 'Stock updated per location. Transaction logged for each.', howToTest: 'HOW TO TEST:\n1. Initiate a batch receive operation for a store item.\n2. Enter qty for Location A: 10 and Location B: 5.\n3. Save.\n4. VERIFY: Location A stock increased by 10, Location B by 5.\n5. VERIFY: Transaction history shows both receive entries.' },
  { id: 'ST-039', section: 'Batch Operations', scenario: 'Batch Consume from specific location', priority: 'High', steps: '1. Select batch Consume\n2. Choose location\n3. Enter quantities\n4. Save', testData: 'Location A: 3', expected: 'Stock consumed from selected location. Other location unchanged.', howToTest: 'HOW TO TEST:\n1. Initiate a batch consume for a store item.\n2. Select Location A and enter qty: 3.\n3. Save.\n4. VERIFY: Location A stock decreased by 3.\n5. VERIFY: Location B stock is unchanged.\n6. Check History for the consume entry.' },
  { id: 'ST-040', section: 'Bulk Operations', scenario: 'Bulk delete/archive multiple items', priority: 'Medium', steps: '1. Select multiple store items\n2. Click Bulk Delete/Archive\n3. Confirm', testData: '5 items selected', expected: 'All selected items archived. Removed from active list. Confirmation before action.', howToTest: 'HOW TO TEST:\n1. In the Stores list, check 5 items via checkboxes.\n2. Click "Bulk Delete" or "Bulk Archive".\n3. VERIFY: A confirmation dialog appears listing the 5 items.\n4. Confirm.\n5. VERIFY: All 5 items are removed from the active list.\n6. VERIFY: If an "Archived" or "Inactive" filter exists, the items appear there.' },
  { id: 'ST-041', section: 'Location Names', scenario: 'Customize Location A/B labels', priority: 'Low', steps: '1. Navigate to Stores settings\n2. Rename Location A to "Paint Locker"\n3. Save', testData: 'New label: "Paint Locker"', expected: 'Location label customized. New name shown across all store views for this vessel.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores settings or admin area.\n2. Find the location label configuration.\n3. Rename "Location A" to "Paint Locker".\n4. Save.\n5. VERIFY: All Stores views now show "Paint Locker" instead of "Location A".\n6. VERIFY: Transaction history also uses the new label.' },
  { id: 'ST-042', section: 'UOM', scenario: 'Select preset unit of measure', priority: 'Low', steps: '1. Add/Edit store item\n2. Select UOM from dropdown\n3. Verify options', testData: 'UOM options: pcs, set, ltr, kg, mtr', expected: 'Dropdown shows all preset UOM options. Selected value saved.', howToTest: 'HOW TO TEST:\n1. Add or edit a store item.\n2. Click the UOM (Unit of Measure) dropdown.\n3. VERIFY: Options include pcs, set, ltr, kg, mtr, and others.\n4. Select "ltr" and save.\n5. VERIFY: The UOM "ltr" is displayed on the item.' },
  { id: 'ST-043', section: 'UOM', scenario: 'Enter custom UOM via "Other"', priority: 'Low', steps: '1. Add/Edit store item\n2. Select "Other" UOM\n3. Enter custom unit\n4. Save', testData: 'Custom: "drum"', expected: 'Custom UOM accepted and saved. Displayed on item details.', howToTest: 'HOW TO TEST:\n1. Add or edit a store item.\n2. Select "Other" from the UOM dropdown.\n3. VERIFY: A text input field appears.\n4. Enter "drum".\n5. Save.\n6. VERIFY: The UOM "drum" is saved and displayed on the item.' },
  { id: 'ST-044', section: 'Stores List', scenario: 'Sort stores by any column', priority: 'Low', steps: '1. Navigate to Stores\n2. Click column headers\n3. Verify sorting', testData: 'Sort by: Code, Name, Qty, Category', expected: 'Items sorted by clicked column. Toggle asc/desc on repeated click.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores.\n2. Click the "Code" column header. VERIFY: Items sort by code ascending.\n3. Click again. VERIFY: Items sort descending.\n4. Repeat with "Name" and "Qty" columns.\n5. VERIFY: Sorting works correctly for each column.' },
  { id: 'ST-045', section: 'Add Store Item', scenario: 'Add item to Lubes category', priority: 'Medium', steps: '1. Go to Lubes tab\n2. Click Add\n3. Fill item details\n4. Save', testData: 'Item: "Cylinder Oil SAE 50"', expected: 'Item created in Lubes category. Visible on Lubes tab.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Lubes tab.\n2. Click "Add Item".\n3. Enter name: "Cylinder Oil SAE 50".\n4. Fill in other required fields.\n5. Save.\n6. VERIFY: The item appears in the Lubes tab list.\n7. VERIFY: It does NOT appear in the Stores or Chemicals tabs.' },
  { id: 'ST-046', section: 'Add Store Item', scenario: 'Add item to Others category', priority: 'Low', steps: '1. Go to Others tab\n2. Click Add\n3. Fill item details\n4. Save', testData: 'Item: "Safety Helmet"', expected: 'Item created in Others category.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Others tab.\n2. Click "Add Item".\n3. Enter name: "Safety Helmet".\n4. Fill in required fields and save.\n5. VERIFY: The item appears in the Others tab.\n6. VERIFY: It does NOT appear in other category tabs.' },
  { id: 'ST-047', section: 'Location View', scenario: 'View items by storage location', priority: 'Medium', steps: '1. Switch to Location sub-view\n2. Verify items grouped by bin/location', testData: 'N/A', expected: 'Items displayed grouped by physical storage location.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores and switch to the "Location" sub-view.\n2. VERIFY: Items are grouped by their physical storage bin or location.\n3. VERIFY: Each location group shows the items stored there with quantities.\n4. VERIFY: All items from the Inventory view appear somewhere in the Location view.' },
  { id: 'ST-048', section: 'Export', scenario: 'Export store items by category', priority: 'Medium', steps: '1. Select category tab (e.g., Chemicals)\n2. Click Export\n3. Download file', testData: 'Category: Chemicals', expected: 'Export contains only items from selected category with all fields.', howToTest: 'HOW TO TEST:\n1. Navigate to Stores > Chemicals tab.\n2. Click the "Export" button.\n3. VERIFY: A file (CSV/Excel) downloads.\n4. Open it and VERIFY: Only chemical items are included.\n5. VERIFY: Columns include chemical-specific fields (UN No, Flash Point, etc.).' },
  { id: 'ST-049', section: 'Edge Cases', scenario: 'Chemical item without expiry date', priority: 'Low', steps: '1. Add chemical without expiry date\n2. Save\n3. Verify display', testData: 'Expiry: blank', expected: 'Item saved. Shows "No expiry" or dash in expiry column.', howToTest: 'HOW TO TEST:\n1. Add a chemical item and leave the Expiry Date field blank.\n2. Save.\n3. VERIFY: The item is saved without errors.\n4. VERIFY: The expiry column shows "No Expiry", a dash, or is blank.\n5. VERIFY: The item is NOT flagged as expired.' },
  { id: 'ST-050', section: 'Edge Cases', scenario: 'Transfer stock between locations', priority: 'Medium', steps: '1. Open store item\n2. Transfer qty from Location A to B\n3. Save', testData: 'Transfer: 5 units A→B', expected: 'Location A decremented, Location B incremented. Transfer transaction logged.', howToTest: 'HOW TO TEST:\n1. Note current stock at Location A and B for a store item.\n2. Initiate a transfer: From Location A, To Location B, Qty: 5.\n3. Save.\n4. VERIFY: Location A decreased by 5, Location B increased by 5.\n5. VERIFY: Total ROB unchanged.\n6. VERIFY: History shows a "Transfer" transaction.' },
];

