// Row 5: Headers
const r5 = summary.addRow(['MODULE', 'SHEET NAME', 'TOTAL TEST CASES', 'PASSED', 'FAILED', 'PASS RATE (%)']);
r5.eachCell(cell => { cell.fill = HEADER_FILL; cell.font = HEADER_FONT; cell.border = BORDER; cell.alignment = { horizontal: 'center', vertical: 'middle' }; });

// Rows 6-17: Data rows with formulas
allSheets.forEach((s, i) => {
  const rowNum = 6 + i;
  const row = summary.addRow([s.label, s.sheet, s.count, null, null, null]);
  row.getCell(4).value = { formula: `COUNTIF('${s.sheet}'!I:I,"Pass")` };
  row.getCell(5).value = { formula: `COUNTIF('${s.sheet}'!I:I,"Fail")` };
  row.getCell(6).value = { formula: `IF(C${rowNum}=0,0,ROUND(D${rowNum}/C${rowNum}*100,1))` };
  row.eachCell(cell => { cell.border = BORDER; cell.alignment = { vertical: 'middle' }; });
  if (i % 2 === 1) row.eachCell(cell => { cell.fill = ALT_FILL; });
});

// Row 18: Total
const totalRow = 6 + allSheets.length;
const rTotal = summary.addRow(['TOTAL', '', null, null, null, null]);
rTotal.getCell(3).value = { formula: `SUM(C6:C${totalRow - 1})` };
rTotal.getCell(4).value = { formula: `SUM(D6:D${totalRow - 1})` };
rTotal.getCell(5).value = { formula: `SUM(E6:E${totalRow - 1})` };
rTotal.getCell(6).value = { formula: `IF(C${totalRow}=0,0,ROUND(D${totalRow}/C${totalRow}*100,1))` };
rTotal.eachCell(cell => { cell.border = BORDER; cell.font = { bold: true, size: 11, name: 'Arial' }; cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDAEEF3' } }; });

// Blank row
summary.addRow([]);

// Test Environment Details
const envHeader = summary.addRow(['TEST ENVIRONMENT DETAILS', '', '', '', '', '']);
summary.mergeCells(`A${envHeader.number}:F${envHeader.number}`);
envHeader.getCell(1).font = { bold: true, size: 12, name: 'Arial', color: { argb: 'FF1F4E78' } };
envHeader.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDAEEF3' } };

const envRows = [
  ['Application', 'PMS — Planned Maintenance System'],
  ['Version', 'v1.0 (UAT)'],
  ['Environment', 'UAT / Staging'],
  ['URL', '[To be provided]'],
  ['Browser', 'Chrome (latest), Firefox (latest), Edge (latest)'],
  ['Test Period', '[Start Date] to [End Date]'],
  ['Test Lead', '[Name]'],
];
envRows.forEach(r => {
  const row = summary.addRow([r[0], r[1]]);
  row.getCell(1).font = { bold: true, size: 10, name: 'Arial' };
  row.getCell(2).font = { size: 10, name: 'Arial' };
});

summary.addRow([]);

// Testing Instructions
const instrHeader = summary.addRow(['TESTING INSTRUCTIONS', '', '', '', '', '']);
summary.mergeCells(`A${instrHeader.number}:F${instrHeader.number}`);
instrHeader.getCell(1).font = { bold: true, size: 12, name: 'Arial', color: { argb: 'FF1F4E78' } };
instrHeader.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDAEEF3' } };

const instructions = [
  '1. Navigate to the relevant module sheet for the area being tested.',
  '2. Follow the Test Steps column exactly as described.',
  '3. Use the Test Data provided (or substitute equivalent valid/invalid data).',
  '4. Compare the actual result with the Expected Result.',
  '5. Mark Pass/Fail in column I. Use "Blocked" if a prerequisite prevents testing.',
  '6. Record any issues, bugs, or observations in the Comments column.',
  '7. Enter your name and the test date in columns K and L.',
  '8. Priority guide: High = must pass for go-live, Medium = important, Low = nice-to-have.',
];
instructions.forEach(instr => {
  const row = summary.addRow([instr]);
  row.getCell(1).font = { size: 10, name: 'Arial' };
});

summary.addRow([]);

// Known Issues
const knownHeader = summary.addRow(['KNOWN ISSUES / LIMITATIONS', '', '', '', '', '']);
summary.mergeCells(`A${knownHeader.number}:F${knownHeader.number}`);
knownHeader.getCell(1).font = { bold: true, size: 12, name: 'Arial', color: { argb: 'FF1F4E78' } };
knownHeader.getCell(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFDAEEF3' } };

const knRow = summary.addRow(['(To be updated during testing)']);
knRow.getCell(1).font = { size: 10, italic: true, name: 'Arial', color: { argb: 'FF999999' } };

// Write
wb.xlsx.writeFile('PMS_Additional_Test_Cases_Complete.xlsx').then(() => {
  const total = allSheets.reduce((s, r) => s + r.count, 0);
  console.log('SUCCESS: Generated PMS_Additional_Test_Cases_Complete.xlsx');
  console.log('Total additional test cases: ' + total);
  console.log('Format: 13 columns (with How to Test)');
  console.log('Summary: 6 columns with COUNTIF formulas');
  allSheets.forEach(s => console.log('  ' + s.label + ': ' + s.count + ' cases'));
});
